tests.command:
run PositiveScenario1 {
    some disj t1, t2 : Track | some disj s1 : Signal {
        Track = t1 + t2
        Signal = s1
        Junction = none
        Entry = t1
        Exit = t2
        Semaphore = s1
        Speed = none
        Track <: succs = t1->t2
        Track <: signals = t1->s1
    }
} for exactly 2 Track, exactly 1 Signal expect 1

